<?php
namespace App\Http\Controllers\Checker;
use App\Http\Controllers\Controller; use App\Models\CheckerAssignment; use App\Models\ScanSession; use App\Models\StockOpnameCycle; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Illuminate\View\View;
class CheckerController extends Controller {
    public function home(Request $request): View { $assignments=CheckerAssignment::query()->with(['cycle','warehouse'])->where('checker_id',$request->user()->id)->whereHas('cycle',fn($q)=>$q->where('status',StockOpnameCycle::STATUS_OPEN))->get()->sortBy(fn($a)=>$a->cycle->cycle_no.'-'.$a->warehouse->warehouse_code); return view('checker.home',compact('assignments')); }
    public function startSession(Request $request, StockOpnameCycle $cycle, int $warehouseId): RedirectResponse { $data=$request->validate(['location'=>['required','string','max:255']]); abort_unless($cycle->status===StockOpnameCycle::STATUS_OPEN,422); $warehouse=$cycle->warehouses()->findOrFail($warehouseId); $assigned=CheckerAssignment::where('cycle_id',$cycle->id)->where('warehouse_id',$warehouse->id)->where('checker_id',$request->user()->id)->exists(); abort_unless($assigned,403); ScanSession::where('checker_id',$request->user()->id)->whereNull('ended_at')->update(['ended_at'=>now()]); $session=ScanSession::create(['cycle_id'=>$cycle->id,'warehouse_id'=>$warehouse->id,'checker_id'=>$request->user()->id,'location'=>trim($data['location']),'started_at'=>now()]); return redirect()->route('checker.scan',$session); }
    public function scanPage(Request $request, ScanSession $session): View { abort_unless((int)$session->checker_id===(int)$request->user()->id,403); abort_if($session->ended_at,422); $session->load(['cycle','warehouse']); abort_unless($session->cycle->status===StockOpnameCycle::STATUS_OPEN,422); return view('checker.scan',compact('session')); }
}
